#!/bin/sh
# Build mt32bridge against Munt's libmt32emu sources (no cmake/Qt/ALSA needed):
#   git clone --depth 1 https://github.com/munt/munt.git ~/.local/src/munt   (once)
#   port/tools/mt32bridge/build.sh [MUNT_SRC]   -> port/tools/mt32bridge/mt32bridge
set -e
cd "$(dirname "$0")"
M=${1:-$HOME/.local/src/munt}/mt32emu/src
B=build; mkdir -p $B
# config.h normally generated by cmake: static C++ API build, no version tagging
sed -e 's/@libmt32emu_VERSION@/2.x/' -e 's/@libmt32emu_VERSION_MAJOR@/2/' -e 's/@libmt32emu_VERSION_MINOR@/0/' \
    -e 's/@libmt32emu_VERSION_PATCH@/0/' -e 's/@libmt32emu_EXPORTS_TYPE@/0/' -e 's/@libmt32emu_SHARED_DEFINITION@//' \
    -e 's/@libmt32emu_RUNTIME_VERSION_CHECK@/0/' $M/config.h.in > $B/config.h
SRC="$(ls $M/*.cpp) $M/sha1/sha1.cpp $M/srchelper/InternalResampler.cpp $(ls $M/srchelper/srctools/src/*.cpp)"
g++ -O2 -std=c++11 -DMT32EMU_WITH_INTERNAL_RESAMPLER -DMT32EMU_API_TYPE=0 -I$B -I$M -I$M/srchelper/srctools/include \
    -w -o mt32bridge mt32bridge.cpp $SRC
echo "built $(pwd)/mt32bridge"
